function unlock(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.connect(audio.destination)}audio.resume().catch(()=>{});master.gain.value=music&&state==='play'?.15*preferences.volume/100:0;nextNote=audio.currentTime}catch(e){}}
function tone(f,d=.1,type='triangle',v=.18,t){if(!audio||!music)return;t=t??audio.currentTime;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.01)}
function soundtrack(){if(!audio||!music||state!=='play')return;let scale=boss?[220,261.63,329.63,293.66,220,392,329.63,293.66]:[261.63,329.63,392,523.25,440,392,329.63,293.66],beat=boss?.16:.23;if(nextNote<audio.currentTime-.2)nextNote=audio.currentTime;while(nextNote<audio.currentTime+.1){tone(scale[note%8],beat*.8,'triangle',.2,nextNote);if(note%2===0)tone(scale[(note>>2)%8]/4,beat*1.5,'square',.1,nextNote);note++;nextNote+=beat}}
