function home(){state='home';panel('Your courier HQ',`An original food-fight dungeon: explore a twelve-floor kitchen campaign, find recipes, and face six regular boss families, crowned champions, and major bosses on floors 3, 6, 9 and 12. Flawless boss fights earn blessings; other victories offer optional maximum-life trades. ${meta.tokens} permanent tokens.${storageOK?' Progress saves in this browser.':' Storage unavailable: progress lasts this session.'}`);for(let k of ['health','power']){let level=meta[k],price=3+3*level;$('choices').append(button(`${k==='health'?'Helmet: +1 starting life':'Seasoning: +0.25 starting damage'} · ${level}/3 · ${price} tokens`,()=>{if(meta.tokens>=price&&meta[k]<3){meta.tokens-=price;meta[k]++;save();home();hideMenu()}},'meta-'+k,level>=3||meta.tokens<price))}$('choices').append(button(coopActive?'Start a fresh co-op run':'Start a fresh kitchen crawl',newRun,'start-run'));$('panel-text').textContent=courier(selectedCourier).name+' selected. '+$('panel-text').textContent;hud();if(!coopActive)showMenu('home','home')}
const items=[{id:'damage',name:'Extra crispy',text:'+1 fry damage.',take:()=>damage++},{id:'rapid',name:'Rush hour',text:'Shoot 25% faster.',take:()=>rate*=1.25},{id:'spread',name:'Family portion',text:'Two extra angled fries (stacks three times).',take:()=>spread++},{id:'pierce',name:'Skewer fries',text:'Fries pierce through snacks.',take:()=>pierce=true},{id:'chili',name:'Chili drizzle',text:'Hits burn enemies for extra damage.',take:()=>chili=true},{id:'bounce',name:'Rubber fries',text:'Fries bounce once off room walls.',take:()=>bounce=true},{id:'health',name:'Bigger bag',text:'+1 max life and heal 3.',take:()=>{maxHP++;heal(3)}},{id:'speed',name:'Fresh wheels',text:'Move 15% faster.',take:()=>moveSpeed=Math.min(2.2,moveSpeed*1.15)}];
