function renderCharacter(){let c=courier(selectedCourier);$('char-name').textContent=c.name;$('char-tag').textContent=c.tag+' / '+c.inspired;$('char-story').textContent=c.story;$('char-portrait').innerHTML=portrait(c);$('char-health').textContent='♥ '.repeat(c.hp)+' · '+c.hp+' lives';
for(let [key,value,reference] of [['damage',c.damage,1.5],['speed',c.speed,1.3],['rate',c.rate,1.25]]){let n=Math.max(1,Math.round(value/reference*5));$('char-'+key).innerHTML='<span class="stat-marks" aria-hidden="true">'+Array.from({length:5},(_,i)=>'<i'+(i<n?' class="filled"':'')+'></i>').join('')+'</span><span>'+value.toFixed(2)+(key==='damage'?' / fry':key==='speed'?'× move':'× fire')+'</span>';}
$('char-passive').hidden=!c.passive;$('char-passive-name').textContent=c.passive||'';$('char-passive-text').textContent=c.passiveText;$('char-active').hidden=!c.active;$('char-active-name').textContent=c.active||'';$('char-active-text').textContent=(c.activeText||'')+(c.active?' '+c.cooldown+'s cooldown · E / Space or ability button.':'');$('char-mode').textContent=selectionPurpose==='solo'?'SOLO EXPEDITION':selectionPurpose==='host'?'CO-OP / YOU ARE THE HOST':'CO-OP / YOU ARE THE GUEST';$('char-confirm').textContent=selectionPurpose==='solo'?'Take '+c.name+' to HQ →':selectionPurpose==='host'?'Host as '+c.name+' →':'Join as '+c.name+' →';for(let ch of couriers){let b=$('choose-'+ch.id);b.setAttribute('aria-pressed',String(ch.id===c.id));b.innerHTML=portrait(ch)+'<span>'+ch.name+'</span>';}$('char-host-choice').textContent=c.name+' selected · '+c.hp+' base lives · '+c.inspired;$('char-join-choice').textContent=$('char-host-choice').textContent;renderMarks();}
