$('menu-solo').onclick=()=>openCharacters('solo');$('menu-host').onclick=()=>openCharacters('host');$('menu-join').onclick=()=>openCharacters('join');$('menu-help').onclick=()=>showMenu('help','home');$('menu-settings').onclick=()=>showMenu('settings','home');$('session-help').onclick=()=>showMenu('help','session');$('session-settings').onclick=()=>showMenu('settings','session');$('menu-back').onclick=menuBack;$('menu-resume').onclick=returnToGame;$('menu-quit').onclick=()=>{menuExitView='session';showMenu('quit','session')};$('confirm-quit').onclick=endFromMenu;$('cancel-quit').onclick=()=>showMenu(menuExitView);$('menu-open').onclick=()=>{if(state==='home'&&!coopActive){showMenu('home','home');return}if(state==='play')pause();showMenu('session','session')};
